import json, gzip, os, sys

STEP_KEEP_KEYS = {'step', 'action', 'modality', 'score_before', 'score_after', 'score_delta'}
MODE_META_KEYS = {'mode', 'task_name', 'variation_idx', 'final_score', 'initial_score', 'num_steps', 'total_time_s'}

def slim_step(step, mode_key):
    out = {k: step[k] for k in STEP_KEEP_KEYS if k in step}
    if mode_key == 'always_deterministic':
        candidates = step.get('candidates', [])
        action = step.get('action')
        for c in candidates:
            if c.get('action') == action:
                out['lethal'] = c.get('lethal', False)
                break
    return out

def slim_mode(mode_data, mode_key):
    if not isinstance(mode_data, dict): return mode_data
    out = {k: mode_data[k] for k in MODE_META_KEYS if k in mode_data}
    if 'steps' in mode_data:
        out['steps'] = [slim_step(s, mode_key) for s in mode_data['steps']]
    if 'action_history' in mode_data:
        out['action_history'] = mode_data['action_history']
    return out

def slim_record(record):
    out = {'episode_idx': record.get('episode_idx'), 'variation_idx': record.get('variation_idx')}
    for mk in ('always_internal', 'always_deterministic'):
        if mk in record: out[mk] = slim_mode(record[mk], mk)
    return out

src = '/proc/957020/fd/3'
out_dir = '/root/autodl-tmp/simgate-modular-routing/results/plan_c/lifespan-longest-lived'
slim_path = os.path.join(out_dir, 'episodes.jsonl')
gz_path = os.path.join(out_dir, 'episodes_full.jsonl.gz')

line_count = 0
print(f'Reading from {src}...', flush=True)
with open(src, 'rb') as fin, open(slim_path, 'w') as fout_slim, gzip.open(gz_path, 'wb', compresslevel=6) as fout_gz:
    for raw_line in fin:
        fout_gz.write(raw_line)
        record = json.loads(raw_line)
        fout_slim.write(json.dumps(slim_record(record), separators=(',', ':')) + '\n')
        line_count += 1
        if line_count % 500000 == 0:
            print(f'  ...{line_count:,} records', flush=True)

print(f'Total: {line_count:,} records', flush=True)
print(f'Slim: {os.path.getsize(slim_path)/1024**3:.2f} GB', flush=True)
print(f'GZ: {os.path.getsize(gz_path)/1024**3:.2f} GB', flush=True)
print('DONE', flush=True)
" > /tmp/slim_recovery.log 2>&1 &
echo "RECOVERY_PID=$!"

