import subprocess
# Check deleted files still held open (consuming disk space)
result = subprocess.run(['find', '/proc', '-maxdepth', '3', '-path', '*/fd/*', '-type', 'l'], capture_output=True, text=True, timeout=5)
import os
deleted = {}
for line in result.stdout.strip().split('\n'):
    if not line: continue
    try:
        target = os.readlink(line)
        if '(deleted)' in target:
            # Get size from /proc/PID/fdinfo or stat
            try:
                sz = os.stat(line).st_size
                deleted[line] = (target, sz)
            except:
                deleted[line] = (target, 0)
    except: pass
for path, (target, sz) in sorted(deleted.items(), key=lambda x: -x[1]):
    print(f'{sz/1e9:.2f}G  {path} -> {target}')
" 2>&1 | head -20
